        assert mcp_matches
        assert dossier.has_direct_agent_evidence is False

    def test_openai_assistants_is_remote_proxy(self) -> None:
        source = """
        import openai

        class AssistantCaller:
            def run(self, client, thread_id, assistant_id):
                run = client.beta.threads.runs.create(
                    thread_id=thread_id,
